  const demoMeterPhoto='poverkadoma-meter-demo.jpg';
  const photoAvailable=name=>Boolean(name&&(demoPhotos.has(name)||photoUrls.has(name)));
  const routes=['acts','new-act','act-editor','meter-editor','measurements','act-review','upload','history','history-act','statistics'];
  const statusName={draft:'Черновик',ready:'Готово к выгрузке',error:'Ошибка отправки',uncertain:'Приём не подтверждён',sent:'Выгружен в макете'};
