    if(!ready.length){if(acts.length===1&&blocked.length===1){const issues=issuesFor(blocked[0]),out=body();out.append(text('Перед выгрузкой нужно выполнить следующие пункты:','muted'),...issues.map(issue=>linkRow(issue.label,()=>{closeModal();navigate(issue.route,issue.params);})));modal({title:'Перед выгрузкой',body:out,actions:[{label:'Вернуться к актам',onClick:closeModal}]});}else notice('Нет готовых актов. Откройте список недостающих данных','error');return;}
    if(api.isOffline()){for(const a of ready){a.status='error';a.error='Нет подключения к интернету. Акт сохранён на устройстве.';}save();notice('Нет интернета. Акты сохранены, повторите после подключения','error');rerender();return;}
