    if(route==='act-editor')return actEditor(act,params);if(route==='act-review')return reviewScreen(act);if(route==='history-act')return historyAct(act);
    const meter=findMeter(act,params.meterId);if(!meter){const out=body();out.append(text('Счётчик не найден'),button('К акту',()=>navigate('act-editor',{id:act.id,tab:'meters'})));return view('Счётчик',out,'Счётчик мог быть удалён из акта.');}
