    if(params.selectedEquipment&&typeof params.selectedEquipment==='object'){const selected=params.selectedEquipment;meter.equipment=String(selected.name||'Средство поверки')+' • '+String(selected.serial||selected.number||selected.id||'');meter.equipmentId=String(selected.id||'');meter.equipmentStatus=String(selected.status||'');meter.equipmentValidUntil=String(selected.validUntil||'');changed(act);delete params.selectedEquipment;delete currentParams.selectedEquipment;}
